const items = $input.all();
const results = [];

const patterns = [
  { name: 'instruction_override', score: 2, regex: /ignore\s+(all\s+)?(previous|prior|earlier|above|old)\s+(instructions?|prompts?|rules?|directives?|context)/i },
  { name: 'instruction_override', score: 2, regex: /disregard\s+(all\s+)?(previous|prior|earlier|above|old)\s+(instructions?|prompts?|rules?|directives?)/i },
  { name: 'instruction_override', score: 2, regex: /forget\s+(all\s+)?(previous|prior|earlier|above|old)\s+(instructions?|prompts?|rules?|directives?)/i },
  { name: 'instruction_override', score: 2, regex: /new\s+instructions?\s*:/i },
  { name: 'role_play_attack', score: 2, regex: /you\s+are\s+now\s+(a\s+|an\s+)?(?!assistant|helpful)/i },
  { name: 'role_play_attack', score: 2, regex: /act\s+as\s+(a\s+|an\s+)?(different|another|alternate|unrestricted|uncensored|evil|malicious)/i },
  { name: 'role_play_attack', score: 2, regex: /pretend\s+(you\s+are|to\s+be)\s+(a\s+|an\s+)?(different|another|unrestricted|uncensored|evil)/i },
  { name: 'privilege_escalation', score: 2, regex: /developer\s+mode/i },
  { name: 'privilege_escalation', score: 2, regex: /jailbreak/i },
  { name: 'privilege_escalation', score: 2, regex: /dan\s+mode/i },
  { name: 'privilege_escalation', score: 2, regex: /god\s+mode/i },
  { name: 'privilege_escalation', score: 2, regex: /sudo\s+mode/i },
  { name: 'privilege_escalation', score: 1, regex: /bypass\s+(all\s+)?(restrictions?|filters?|rules?|guidelines?|policies?|safety)/i },
  { name: 'system_delimiter', score: 2, regex: /<\|system\|>/i },
  { name: 'system_delimiter', score: 2, regex: /\[INST\]/i },
  { name: 'system_delimiter', score: 2, regex: /<<SYS>>/i },
  { name: 'system_delimiter', score: 2, regex: /<\|im_start\|>/i },
  { name: 'system_delimiter', score: 2, regex: /###\s*system/i },
  { name: 'prompt_leakage', score: 1, regex: /reveal\s+(the\s+)?(system\s+prompt|your\s+prompt|your\s+instructions?|your\s+rules?)/i },
  { name: 'prompt_leakage', score: 1, regex: /print\s+(the\s+)?(system\s+prompt|your\s+prompt|your\s+instructions?)/i },
  { name: 'prompt_leakage', score: 1, regex: /what\s+(are|were)\s+your\s+(instructions?|rules?|guidelines?|directives?)/i },
];

for (const item of items) {
  const input = String(item.json.input || '');
  const matched = [];
  let totalScore = 0;

  for (const pattern of patterns) {
    if (pattern.regex.test(input)) {
      const existing = matched.find(m => m.category === pattern.name);
      if (!existing) {
        matched.push({ category: pattern.name, score: pattern.score });
        totalScore += pattern.score;
      }
    }
  }

  const blocked = totalScore >= 2;

  results.push({
    json: {
      ...item.json,
      scan_result: {
        blocked,
        risk_score: totalScore,
        matched_categories: matched.map(m => m.category),
        matched_count: matched.length,
      },
    },
  });
}

return results;
